components.css:
.ds-recent-plan-stack { position: relative; isolation: isolate; width: min(100% - 24px, 375px); min-width: 0; }
.ds-recent-plan-stack::before, .ds-recent-plan-stack::after { content: ""; position: absolute; inset: 6% 5% 0 4%; border-radius: 4px; z-index: -1; }
.ds-recent-plan-stack::before { background: #91affc; transform: translate(20px, 0) rotate(7deg); box-shadow: 0 15px 42px rgb(13 32 109 / 27%); }
.ds-recent-plan-stack::after { background: #d1ddff; transform: translate(6px, 4px) rotate(3deg); }
.ds-recent-plan { display: grid; gap: 6px; padding: 16px 19px; border-radius: 4px; background: #fbfcff; color: #172651; box-shadow: 0 17px 38px rgb(9 32 112 / 27%); text-decoration: none; font-family: var(--font-ui, Inter, Arial, sans-serif); transition: transform 240ms var(--cobalt-ease, cubic-bezier(.18, .76, .26, 1)); }
.ds-recent-plan:hover { transform: translateY(-4px); }
.ds-recent-plan:focus-visible { outline: 3px solid white; outline-offset: 5px; }
.ds-recent-plan-label, .ds-recent-plan-progress, .ds-recent-plan-open { display: flex; align-items: center; gap: 6px; font-size: 13px; }
.ds-recent-plan-label, .ds-recent-plan-task { color: #475c8a; font-size: 13px; }
.ds-recent-plan strong { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; overflow-wrap: anywhere; font: 720 24px/1.2 var(--font-heading, Montserrat, Inter, Arial, sans-serif); letter-spacing: -.03em; }
.ds-recent-plan-task { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-recent-plan-details { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; margin-top: 4px; border-top: 1px solid #d3ddfa; padding-top: 9px; }
.ds-recent-plan-track { display: block; width: 52px; height: 4px; border-radius: 4px; background: #dae3fc; overflow: hidden; }
.ds-recent-plan-track > span { display: block; height: 100%; background: #3358df; transform-origin: left; }
.ds-recent-plan-open { color: #2445b7; font-weight: 650; }
@media (max-width: 767px) { .ds-recent-plan-stack { width: 100%; } .ds-recent-plan-stack::before, .ds-recent-plan-stack::after { display: none; } .ds-recent-plan { grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; padding: 7px 10px; min-height: 49px; box-shadow: none; } .ds-recent-plan-label { grid-column: 1; font-size: 12px; } .ds-recent-plan strong { grid-column: 1; font-size: 15px; } .ds-recent-plan-task, .ds-recent-plan-progress { display: none; } .ds-recent-plan-details { grid-column: 2; grid-row: 1 / 3; border: 0; padding: 0; margin: 0; } .ds-recent-plan-open { font-size: 12px; } }
@media (prefers-reduced-motion: no-preference) { .ds-recent-plan-stack::before, .ds-recent-plan-stack::after { animation: ds-council-stack-open 720ms var(--cobalt-ease, cubic-bezier(.18, .76, .26, 1)) both; } .ds-recent-plan-track > span { animation: ds-council-progress-in 490ms var(--cobalt-ease, cubic-bezier(.18, .76, .26, 1)) 220ms both; } }
@media (prefers-reduced-motion: reduce) { .ds-recent-plan { transition: none; } .ds-recent-plan:hover { transform: none; } }
@keyframes ds-council-stack-open { from { transform: none; } }
@keyframes ds-council-progress-in { from { transform: scaleX(0); } }

.ds-dashboard-filters { display: flex; flex-wrap: wrap; gap: 1px 12px; padding: 0 14px; border-bottom: 1px solid var(--ui-border, #dce1e9); background: var(--background, #fff); }
.ds-dashboard-filter { position: relative; min-height: 44px; padding: 5px 3px; border: 0; background: transparent; color: var(--ui-secondary, #525b6b); font: 14px var(--font-ui, Inter, Arial, sans-serif); cursor: pointer; }
.ds-dashboard-filter::after { content: ""; position: absolute; inset: auto 0 0; height: 2px; background: var(--primary, #132fc1); transform: scaleX(0); transition: transform 220ms var(--cobalt-ease, cubic-bezier(.18, .76, .26, 1)); }
.ds-dashboard-filter[aria-pressed="true"] { color: var(--primary, #132fc1); font-weight: 650; }
.ds-dashboard-filter[aria-pressed="true"]::after { transform: scaleX(1); }
.ds-dashboard-filter:focus-visible { outline: 2px solid var(--ring, #132fc1); outline-offset: -2px; }
@media (max-width: 767px) { .ds-dashboard-filters { padding-inline: 8px; gap: 0 7px; } .ds-dashboard-filter { font-size: 12px; padding-inline: 1px; } }
@media (max-width: 360px) { .ds-dashboard-filter { font-size: 11px; } }
@media (prefers-reduced-motion: reduce) { .ds-dashboard-filter::after { transition: none; } }
